import { createHash } from 'node:crypto';
import * as fs from 'node:fs';
import * as path from 'node:path';
import { expect, test } from '@playwright/test';
import type { Frame } from '@playwright/test';
import { launchVsCodeWithFixtures } from './vscodeHarness';

// A genuine manufacturer-independent, vendor-installed KiCad demo.
// This is not an autogenerated sparse 12-layer fixture.
const demoDir = path.join(
  process.env.ProgramFiles ?? String.raw`C:\Program Files`,
  'KiCad',
  '10.0',
  'share',
  'kicad',
  'demos',
  'vme-wren'
);
const boardName = 'vme-wren.kicad_pcb';

function hash(fileName: string): string {
  return createHash('sha256').update(fs.readFileSync(fileName)).digest('hex');
}

test('Windows real dense KiCad 12-layer VME Wren renders with explicit higher viewer memory threshold', async () => {
  test.skip(
    process.platform !== 'win32' ||
      process.env.KICADSTUDIO_LOCAL_WINDOWS_ACCEPTANCE !== '1' ||
      !fs.existsSync(path.join(demoDir, boardName)),
    'Opt-in local Windows with genuine KiCad 10 VME Wren demo only'
  );
  test.setTimeout(180_000);

  const sourcePath = path.join(demoDir, boardName);
  const sourceHash = hash(sourcePath);
  const prefix = fs
    .readFileSync(sourcePath)
    .subarray(0, 20000)
    .toString('utf8');
  const layersTable =
    prefix.split('(layers', 2)[1]?.split('(setup', 1)[0] ?? '';
  const copperLayers =
    layersTable.match(/\(\d+\s+"(?:F|B|In\d+)\.Cu"\s+\w+/g) ?? [];
  expect(copperLayers).toHaveLength(12);
  console.log('WINDOWS_DENSE_VME_COPPER_LAYERS=' + copperLayers.length);
  const start = Date.now();
  const mark = (stage: string) =>
    console.log(`WINDOWS_DENSE_VME ${stage} +${Date.now() - start}ms`);
  const session = await launchVsCodeWithFixtures({
    workspaceSourcePath: demoDir,
    // The shipped default protects memory by switching files >10 MiB to
    // metadata-only. This acceptance deliberately opts in for a 72 MB board.
    settings: {
      'kicadstudio.viewer.largeFileThresholdBytes': 110 * 1024 * 1024
    }
  });
  const copiedFile = path.join(session.workspacePath, boardName);
  mark('VSCODE_READY');

  try {
    expect(hash(copiedFile)).toBe(sourceHash);
    await expect(session.page.locator('.statusbar')).toContainText('MCP', {
      timeout: 40_000
    });
    mark('EXTENSION_ACTIVATED');
    // The dense demo folder can outgrow Explorer's virtualized visible rows;
    // use the native Quick Open path rather than assuming the file is painted
    // in the visible tree viewport.
    const picker = session.page.locator('.quick-input-widget');
    await session.page.keyboard.press('Control+P');
    await expect(picker).toBeVisible();
    await picker.locator('input').fill(boardName);
    await expect(picker).toContainText(boardName, { timeout: 30_000 });
    await session.page.keyboard.press('Enter');
    await expect(picker).toBeHidden();
    await expect(session.page.locator('.tab.active')).toContainText(boardName, {
      timeout: 40_000
    });
    mark('EDITOR_TAB_OPENED');

    let viewer: Frame | undefined;
    await expect
      .poll(
        async () => {
          for (const frame of session.page.frames()) {
            if (await frame.locator('#viewer-engine-badge').count()) {
              viewer = frame;
              return true;
            }
          }
          return false;
        },
        { timeout: 90_000 }
      )
      .toBe(true);

    if (!viewer) throw new Error('Native custom PCB editor never mounted.');
    mark('VIEWER_WEBVIEW_MOUNTED');
    await expect(viewer.locator('#viewer-engine-badge')).toHaveText(
      'KiCanvas',
      {
        timeout: 110_000
      }
    );
    await expect(viewer.locator('#viewer-status')).toContainText(
      'Interactive renderer loaded',
      { timeout: 110_000 }
    );
    mark('INTERACTIVE_RENDERER_LOADED');
    await viewer.locator('#side-panel-toggle').click();
    await expect(viewer.locator('#layers-section')).toBeVisible();
    const names = await viewer.locator('#layers-section').innerText();
    expect(names).toContain('In10.Cu');
    const netsLabel = (await viewer.locator('#net-count').innerText()).trim();
    const netCount = Number.parseInt(netsLabel, 10);
    expect(netCount).toBeGreaterThan(1000);
    console.log(`WINDOWS_DENSE_VME_VISIBLE_NETS=${netCount}`);

    await viewer.getByRole('button', { name: 'Focus In10.Cu' }).click();
    await viewer.locator('#layer-solo-btn').click();
    await expect(viewer.locator('#layer-count')).toContainText('1/');
    await viewer.locator('#all-layers-btn').click();
    await expect(viewer.locator('#layer-solo-btn')).toHaveAttribute(
      'aria-pressed',
      'false'
    );
    mark('INNER_LAYER_INTERACTIONS_DONE');

    expect(hash(copiedFile)).toBe(sourceHash);
    expect(hash(sourcePath)).toBe(sourceHash);
    mark('FILE_HASHES_PRESERVED');
    console.log('WINDOWS_REAL_DENSE_12_COPPER_INTERACTIVE=PASS');
    await test.info().attach('windows-vme-wren-12-copper', {
      body: await session.page.screenshot({ fullPage: true }),
      contentType: 'image/png'
    });
  } catch (error) {
    mark('TEST_FAILED');
    console.log(
      'WINDOWS_DENSE_VME_STATUS=' +
        JSON.stringify(
          await session.page
            .locator('.statusbar')
            .allInnerTexts()
            .catch(() => [])
        )
    );
    console.log(
      'WINDOWS_DENSE_VME_TABS=' +
        JSON.stringify(
          await session.page
            .locator('.tab.active')
            .allInnerTexts()
            .catch(() => [])
        )
    );
    console.log(
      'WINDOWS_DENSE_VME_LOGS=' + JSON.stringify(session.logs.slice(-8))
    );
    throw error;
  } finally {
    await session.close();
    mark('SESSION_CLOSED');
  }
});

test('Windows real dense 12-layer board communicates the default metadata-only safety fallback', async () => {
  test.skip(
    process.platform !== 'win32' ||
      process.env.KICADSTUDIO_LOCAL_WINDOWS_ACCEPTANCE !== '1' ||
      !fs.existsSync(path.join(demoDir, boardName)),
    'Opt-in local Windows with genuine KiCad 10 VME Wren demo only'
  );
  test.setTimeout(70_000);

  const sourcePath = path.join(demoDir, boardName);
  const originalHash = hash(sourcePath);
  const session = await launchVsCodeWithFixtures({
    workspaceSourcePath: demoDir
  });
  try {
    const copiedPath = path.join(session.workspacePath, boardName);
    expect(hash(copiedPath)).toBe(originalHash);
    await expect(session.page.locator('.statusbar')).toContainText('MCP', {
      timeout: 30_000
    });
    const picker = session.page.locator('.quick-input-widget');
    await session.page.keyboard.press('Control+P');
    await expect(picker).toBeVisible();
    await picker.locator('input').fill(boardName);
    await expect(picker).toContainText(boardName, { timeout: 30_000 });
    await session.page.keyboard.press('Enter');
    await expect(session.page.locator('.tab.active')).toContainText(boardName);

    let viewer: Frame | undefined;
    await expect
      .poll(
        async () => {
          for (const frame of session.page.frames()) {
            if (await frame.locator('#viewer-engine-badge').count()) {
              viewer = frame;
              return true;
            }
          }
          return false;
        },
        { timeout: 30_000 }
      )
      .toBe(true);
    if (!viewer) throw new Error('Dense board custom editor did not mount.');

    const badge = viewer.locator('#viewer-engine-badge');
    await expect(badge).toHaveText('Metadata only');
    await expect(badge).toHaveAttribute(
      'title',
      /Interactive render is disabled for files larger than 10 MB/
    );
    console.log('WINDOWS_DENSE_VME_DEFAULT_METADATA_GUARD=PASS');
    expect(hash(sourcePath)).toBe(originalHash);
    expect(hash(copiedPath)).toBe(originalHash);
    await test.info().attach('windows-dense-vme-default', {
      body: await session.page.screenshot({ fullPage: true }),
      contentType: 'image/png'
    });
  } finally {
    await session.close();
  }
});
